const aiText = $('IA - Selecionar Conteúdo Inédito & Recente').first().json.text;
const tavilyJson = $input.first().json;

const aiData = JSON.parse(aiText.match(/\{[\s\S]*\}/)[0]);
const rawImages = tavilyJson.images || [];

const validImages = rawImages.filter(url => {
  if (!url || typeof url !== 'string') return false;
  const lower = url.toLowerCase();
  if (lower.includes('lookaside') || lower.includes('facebook.com') || lower.includes('instagram.com') || lower.includes('gemini-generated') || lower.includes('cnews24')) return false;
  return true;
});

const fallbackPhotos = [
  "https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&w=1080&q=80",
  "https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&w=1080&q=80",
  "https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=1080&q=80",
  "https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=1080&q=80",
  "https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?auto=format&fit=crop&w=1080&q=80"
];

if (Array.isArray(aiData.slides)) {
  aiData.slides = aiData.slides.map((slide, idx) => {
    if (validImages.length > 0) {
      slide.image_url = validImages[idx % validImages.length];
    } else {
      slide.image_url = fallbackPhotos[idx % fallbackPhotos.length];
    }
    return slide;
  });
}

const cleanTopic = (aiData.topic || '').replace(/—\s*/g, '').replace(/–\s*/g, '');
const cleanCaption = (aiData.linkedin_caption || '').replace(/—\s*/g, '').replace(/–\s*/g, '');
const slidesJsonStr = JSON.stringify(aiData.slides).replace(/—\s*/g, '').replace(/–\s*/g, '');

const topicSql = cleanTopic.replace(/'/g, "''");
const captionSql = cleanCaption.replace(/'/g, "''");
const slidesSql = slidesJsonStr.replace(/'/g, "''");

return [{ 
  json: { 
    ai_data: aiData, 
    tavily_images: validImages,
    topic_sql: topicSql,
    caption_sql: captionSql,
    slides_sql: slidesSql
  } 
}];

const fs = require('fs');
const http = require('http');
const https = require('https');

const tplLinkedin = fs.readFileSync('/data/media/template_linkedin.html', 'utf8');
const tplInstagram = fs.readFileSync('/data/media/template_instagram.html', 'utf8');

const inputItem = $input.first().json;
const postId = inputItem.id || 'test_post';
let linkedinCaption = (inputItem.linkedin_caption || '').replace(/—\s*/g, '').replace(/–\s*/g, '');

let rawSlides = inputItem.slides_data || inputItem.slides;
if (typeof rawSlides === 'string') {
  try { rawSlides = JSON.parse(rawSlides); } catch(e) {}
}

let slidesData = [];
if (Array.isArray(rawSlides)) {
  slidesData = rawSlides;
} else if (rawSlides && typeof rawSlides === 'object') {
  if (Array.isArray(rawSlides.slides)) slidesData = rawSlides.slides;
  else if (Array.isArray(rawSlides.data)) slidesData = rawSlides.data;
}

function downloadImage(url, destPath) {
  return new Promise((resolve) => {
    if (!url || !url.startsWith('http')) return resolve('');
    const client = url.startsWith('https') ? https : http;
    const req = client.get(url, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        return downloadImage(res.headers.location, destPath).then(resolve);
      }
      if (res.statusCode !== 200) return resolve('');
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => {
        const buf = Buffer.concat(chunks);
        if (buf.length > 3000) {
          fs.writeFileSync(destPath, buf);
          fs.chmodSync(destPath, 0o644);
          resolve(true);
        } else resolve('');
      });
    });
    req.on('error', () => resolve(''));
    req.setTimeout(8000, () => { req.destroy(); resolve(''); });
  });
}

function postToBrowserless(html) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify({
      html: html,
      viewport: { width: 1080, height: 1350, deviceScaleFactor: 2 }
    });
    const req = http.request({
      hostname: 'content_browserless',
      port: 3000,
      path: '/screenshot?token=senha_segura_123',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    }, (res) => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => resolve(Buffer.concat(chunks)));
    });
    req.on('error', reject);
    req.write(postData);
    req.end();
  });
}

function callPdfBuilder(postId) {
  return new Promise((resolve) => {
    const req = http.request({
      hostname: '172.18.0.1',
      port: 9876,
      path: `/build-pdf?post_id=${postId}`,
      method: 'GET'
    }, (res) => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => resolve(Buffer.concat(chunks).toString()));
    });
    req.on('error', (e) => resolve('PDF_ERROR: ' + e.message));
    req.setTimeout(30000, () => { req.destroy(); resolve('PDF_TIMEOUT'); });
    req.end();
  });
}

async function run() {
  const linkedinMediaUrls = [];
  const instagramMediaUrls = [];
  if (slidesData.length === 0) {
    throw new Error('Nenhum slide encontrado na entrada!');
  }

  for (const slide of slidesData) {
    const num = slide.slide_number || 1;
    const tot = slide.total_slides || slidesData.length;
    let title = (slide.title || '').replace(/—\s*/g, '').replace(/–\s*/g, '');
    let body = (slide.body || '').replace(/—\s*/g, '').replace(/–\s*/g, '');
    let imageUrl = slide.image_url || '';

    let coverHtml = '';
    if (imageUrl) {
      const localImgName = `tavily_web_${postId}_${num}.jpg`;
      const localImgPath = `/data/media/${localImgName}`;
      const downloaded = await downloadImage(imageUrl, localImgPath);
      if (downloaded) {
        const imgBuf = fs.readFileSync(localImgPath);
        const base64Img = imgBuf.toString('base64');
        const ext = localImgName.endsWith('.png') ? 'png' : 'jpg';
        coverHtml = `<div class="cover-image-box"><img src="data:image/${ext};base64,${base64Img}" /></div>`;
      }
    }

    const quote = (slide.quote || '').replace(/—\s*/g, '').replace(/–\s*/g, '');
    const quoteHtml = quote ? `<div class="quote-box" style="white-space: pre-wrap; font-family: monospace; font-style: normal; font-size: 24px;">${quote}</div>` : '';

    // Renderizar Slide LinkedIn
    const renderedLinkedin = tplLinkedin
      .replace('{{SLIDE_TITLE}}', title)
      .replace('{{SLIDE_BODY}}', body)
      .replace('{{HIGHLIGHT_BOX}}', quoteHtml)
      .replace('{{COVER_IMAGE_HTML}}', coverHtml);

    const linkedinImgBuf = await postToBrowserless(renderedLinkedin);
    const linkedinFilename = `carousel_${postId}_slide_${num}.png`;
    fs.writeFileSync(`/data/media/${linkedinFilename}`, linkedinImgBuf);
    fs.chmodSync(`/data/media/${linkedinFilename}`, 0o644);
    linkedinMediaUrls.push(`https://conteudos.icarodev.cloud/${linkedinFilename}`);

    // Renderizar Slide Instagram
    const renderedInstagram = tplInstagram
      .replace('{{SLIDE_NUMBER}}', String(num))
      .replace('{{TOTAL_SLIDES}}', String(tot))
      .replace('{{SLIDE_TITLE}}', title)
      .replace('{{SLIDE_BODY}}', body)
      .replace('{{HIGHLIGHT_BOX}}', quoteHtml)
      .replace('{{COVER_IMAGE_HTML}}', coverHtml);

    const instagramImgBuf = await postToBrowserless(renderedInstagram);
    const instagramFilename = `instagram_${postId}_slide_${num}.png`;
    fs.writeFileSync(`/data/media/${instagramFilename}`, instagramImgBuf);
    fs.chmodSync(`/data/media/${instagramFilename}`, 0o644);
    instagramMediaUrls.push(`https://conteudos.icarodev.cloud/${instagramFilename}`);
  }

  const pdfResult = await callPdfBuilder(postId);
  const pdfUrl = `https://conteudos.icarodev.cloud/carousel_${postId}.pdf`;
  return [{
    json: {
      id: postId,
      media_urls: linkedinMediaUrls,
      instagram_media_urls: instagramMediaUrls,
      pdf_url: pdfUrl,
      linkedin_caption: linkedinCaption
    }
  }];
}

return run();

const srcName = "TechCrunch - RSS (Startups)";
const category = "Startups, Funding & Negócios (rodadas de investimento, IPOs, aquisições, unicórnios)";
const rawData = $input.first().json;

const items = [];
let feedData = rawData;

// Try RSS 2.0 format
if (feedData.rss && feedData.rss.channel && feedData.rss.channel.item) {
  const itemArr = Array.isArray(feedData.rss.channel.item) ? feedData.rss.channel.item : [feedData.rss.channel.item];
  itemArr.slice(0, 6).forEach(item => {
    items.push({
      source: srcName,
      title: item.title || '',
      link: item.link || '',
      desc: (item.description || '').replace(/<[^>]+>/g, '').substring(0, 300),
      pubDate: item.pubDate || ''
    });
  });
}

return [{ json: {
  candidate_articles: items.slice(0, 6),
  source_name: srcName,
  foco_do_dia: category,
  hashtag_do_dia: "#Startups #Funding #Negocios",
  total_sources: 6
} }];

